@@ -0,0 +1,32 @@
+import { daysLeft, isExpired } from "./expiry.js";
+
+/** Builds the stock report for `items` as of `now`. */
+export function buildReport(items, now = Date.now()) {
+  const expired = [];
+  const live = [];
+  for (const item of items) (isExpired(item, now) ? expired : live).push(item);
+
+  const byTag = {};
+  for (const item of live)
+    for (const tag of item.tags ?? []) byTag[tag] = (byTag[tag] ?? 0) + 1;
+
+  return {
+    generatedAt: new Date(now).toISOString(),
+    total: live.length,
+    units: live.reduce((sum, i) => sum + i.qty, 0),
+    byTag: Object.fromEntries(
+      Object.entries(byTag).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)),
+    ),
+    expiringSoon: live
+      .filter((i) => daysLeft(i, now) <= 3)
+      .sort(
+        (a, b) =>
+          Date.parse(a.expires) - Date.parse(b.expires) ||
+          (a.name < b.name ? -1 : a.name > b.name ? 1 : 0),
+      )
+      .map((i) => i.name),
+    expired: expired
+      .map((i) => i.name)
+      .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0)),
+  };
+}
